#!/usr/bin/env bash
# Inject onboarding or returning-project context for /de:start.
# ALWAYS injects DESIGN_ENGINEER_PLUGIN_ROOT for reference file resolution.
# Three cases:
#   1. No config → inject full onboarding sequence + plugin root
#   2. Config with project_type: existing → inject existing-project context + plugin root
#   3. Config with project_type: new → inject plugin root only

# Resolve plugin root from this script's location
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
PLUGIN_ROOT="$(dirname "$SCRIPT_DIR")"

CONFIG=".design-engineer-plugin/config.yaml"

if [ ! -f "$CONFIG" ]; then
  # Case 1: No config — full onboarding sequence + plugin root
  cat <<HOOK_EOF
{"hookSpecificOutput":{"hookEventName":"UserPromptSubmit","additionalContext":"DESIGN_ENGINEER_PLUGIN_ROOT: $PLUGIN_ROOT\n\nDESIGN_ENGINEER_PROJECT_STATE: new_to_plugin\n\nONBOARDING SEQUENCE — follow these steps when /de:start runs. Do not skip any step.\n\nSTEP 1: Show this brief intro, then ask the question:\n\n  Output this text first (exactly as written):\n  \"Design Engineer Plugin – a swiss knife for product design. Research, psychology, prototyping, development – all in one tool. You run one command, it figures out where you are, and opens the right instrument.\"\n\n  Then ask:\n  question=\"Welcome to Design Engineer Plugin. What brings you here?\"\n  header=\"Project type\"\n  options=[{label: \"New product\", description: \"Starting from scratch – I have an idea or a problem I want to solve\"}, {label: \"Existing project\", description: \"I already have a product, codebase, or designs – I want to improve, review, or add features\"}]\n\nAfter receiving the answer, follow the matching path:\n\nPATH A — \"New product\":\n  Load the meta-setup skill and proceed to its Step 2 (Detect Environment). The meta-setup skill handles the full new-product setup.\n\nPATH B — \"Existing project\":\n  Continue with steps 2–4 below. Do not skip any.\n\n  STEP 2: Ask goal AND mode in ONE AskUserQuestion call (both questions on the same screen):\n    questions:\n      - question=\"What would you like to do?\" header=\"Goal\" options=[{label: \"Review my project\", description: \"Find issues with UX, accessibility, visual quality, or psychology\"}, {label: \"Implement from Figma\", description: \"Turn Figma designs into production code\"}, {label: \"Design a new feature\", description: \"Think through a new feature before building – research, strategy, design\"}, {label: \"Set up development\", description: \"Configure the AI build pipeline – CLAUDE.md, agents, testing, GitHub\"}]\n      - question=\"How do you want to work?\" header=\"Mode\" options=[{label: \"Guided mode (Recommended)\", description: \"I explain my thinking, show findings one at a time, and wait for your input at each step\"}, {label: \"Autopilot\", description: \"I plan and execute everything, then show you the results. Faster but you review after, not during.\"}]\n\n  STEP 3: Run setup silently, then ask status line:\n    a) Run detect-environment.sh from $PLUGIN_ROOT/skills/meta-setup/scripts/detect-environment.sh. Do NOT launch Explore agents or scan the project separately.\n    b) Create .design-engineer-plugin/ directory and write config.yaml inside it with project_type, selected mode, goal, and detected environment.\n    c) Scaffold documents/design/ folder via $PLUGIN_ROOT/skills/meta-setup/scripts/init-project-structure.sh.\n    d) Show brief environment results in plain language. Only show tech stack and tool connections. Do NOT show Git status, CLAUDE.md status, or developer internals.\n    e) Explain: \"The status line appears below your prompt and shows your model, how much context you have used, and your usage limits.\"\n    f) Ask status line question. Do NOT use the built-in statusline-setup agent. Instead copy the script manually: cp $PLUGIN_ROOT/hooks/de-statusline.js ~/.claude/hooks/de-statusline.js, then read ~/.claude/settings.json and set statusLine to {\"type\": \"command\", \"command\": \"node ~/.claude/hooks/de-statusline.js\"}, write back.\n       question=\"Would you like to install the status line?\"\n       header=\"Status line\"\n       options=[{label: \"Yes (Recommended)\", description: \"Shows model, context usage, and rate limits below every prompt\"}, {label: \"No\", description: \"Skip – re-run /de:start later to install\"}]\n\n  STEP 4: Say \"You're all set. Let's get started.\" then show: \"Tip: Run /de:help anytime to see all available commands and capabilities.\" Then load the /de: command matching the goal:\n    Review my project -> /de:review\n    Implement from Figma -> /de:dev\n    Design a new feature -> /de:design\n    Set up development -> /de:dev\n\nIf user selected \"New product\" in step 1, skip steps 2-4 and load the meta-setup skill at Step 2 (Detect Environment) instead."}}
HOOK_EOF

elif grep -q "project_type: existing" "$CONFIG" 2>/dev/null; then
  # Case 2: Config exists with project_type: existing — show capabilities via AskUserQuestion + plugin root
  cat <<HOOK_EOF
{"hookSpecificOutput":{"hookEventName":"UserPromptSubmit","additionalContext":"DESIGN_ENGINEER_PLUGIN_ROOT: $PLUGIN_ROOT\n\nDESIGN_ENGINEER_PROJECT_STATE: existing_project\n\nThis project has the Design Engineer Plugin configured as an existing project. When /de:start runs:\n\n1. Do NOT show returning-pipeline state or resume information.\n2. Present available commands via AskUserQuestion:\n   question=\"What would you like to do?\"\n   header=\"Goal\"\n   options=[{label: \"Review my project\", description: \"Find issues with UX, accessibility, visual quality, or psychology\"}, {label: \"Implement from Figma\", description: \"Turn Figma designs into production code\"}, {label: \"Design a new feature\", description: \"Think through a new feature before building\"}, {label: \"Set up development\", description: \"Configure the AI build pipeline\"}]\n3. After the user answers, load the matching /de: command directly.\n4. Do NOT mention config files, project types, or detection state.\n5. Do NOT greet the user with the project name or any information from auto-memory. Do not say \"Welcome back\" or reference previous sessions. Just present the AskUserQuestion immediately."}}
HOOK_EOF

else
  # Case 3: Config exists with project_type: new (or other) — inject plugin root only
  cat <<HOOK_EOF
{"hookSpecificOutput":{"hookEventName":"UserPromptSubmit","additionalContext":"DESIGN_ENGINEER_PLUGIN_ROOT: $PLUGIN_ROOT"}}
HOOK_EOF
fi
